-- Backfill of each reporter's "known for" sentence, shown on the back of their card in the Reporters tab.
-- Each sentence states the reporter's lasting impact, checked against reliable sources. seed_figures.sql carries the same values.
-- Bumps updated_at so devices pick the sentences up on their next figure sync rather than at the weekly full sync.
-- Run in the Supabase SQL Editor whenever the sentences change. Each UPDATE matches on id and name, so a row whose name
-- differs changes nothing. Re-running with unchanged sentences changes nothing but updated_at.
BEGIN;

ALTER TABLE figures ADD COLUMN IF NOT EXISTS known_for TEXT NOT NULL DEFAULT '';

UPDATE figures SET known_for = 'Luther published 95 theses against the sale of indulgences, which sparked the Protestant Reformation.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 1 AND name = 'Martin Luther';
UPDATE figures SET known_for = 'Calvin wrote the Institutes of the Christian Religion, which became the defining text of Reformed and Presbyterian churches around the world.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 2 AND name = 'John Calvin';
UPDATE figures SET known_for = 'Bonhoeffer helped lead church resistance to the Nazis, and Letters and Papers from Prison shaped Christian thought after the war.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 3 AND name = 'Dietrich Bonhoeffer';
UPDATE figures SET known_for = 'Spurgeon preached at London''s Metropolitan Tabernacle for decades, and his sermons were printed weekly and read around the world.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 4 AND name = 'Charles Spurgeon';
UPDATE figures SET known_for = 'Wesley led the Methodist revival in Britain, which grew into a worldwide family of Methodist churches.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 5 AND name = 'John Wesley';
UPDATE figures SET known_for = 'Wycliffe challenged church power and inspired the first complete translation of the Bible into English.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 6 AND name = 'John Wycliffe';
UPDATE figures SET known_for = 'Tyndale translated the New Testament into English straight from the Greek, laying the groundwork for the King James Bible.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 7 AND name = 'William Tyndale';
UPDATE figures SET known_for = 'Edwards helped lead the First Great Awakening and wrote Religious Affections, a study of how to tell lasting conversion from passing emotion.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 8 AND name = 'Jonathan Edwards';
UPDATE figures SET known_for = 'Whitefield preached to huge crowds in Britain and America, and his tours made the Great Awakening the first movement shared across the colonies.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 9 AND name = 'George Whitefield';
UPDATE figures SET known_for = 'Knox led the Reformation in Scotland and helped found the Presbyterian Church of Scotland.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 10 AND name = 'John Knox';
UPDATE figures SET known_for = 'Zwingli began the Reformation in Zurich in 1519 and is regarded as the founder of the Reformed tradition of Protestant churches.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 11 AND name = 'Ulrich Zwingli';
UPDATE figures SET known_for = 'Melanchthon wrote the Augsburg Confession, the main statement of Lutheran belief.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 12 AND name = 'Philip Melanchthon';
UPDATE figures SET known_for = 'Barth wrote Church Dogmatics and largely drafted the Barmen Declaration, which opposed Nazi influence in the church.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 13 AND name = 'Karl Barth';
UPDATE figures SET known_for = 'Owen was a leading Puritan theologian, and his books on fighting sin still shape how Reformed Christians pursue holiness.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 14 AND name = 'John Owen';
UPDATE figures SET known_for = 'Baxter turned Kidderminster into a model parish, and his book The Reformed Pastor still guides how ministers care for their people.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 15 AND name = 'Richard Baxter';
UPDATE figures SET known_for = 'Cranmer compiled the Book of Common Prayer, whose words still shape worship in Anglican churches around the world.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 16 AND name = 'Thomas Cranmer';
UPDATE figures SET known_for = 'Bucer led the Reformation in Strasbourg and influenced both Calvin and the English prayer book while teaching at Cambridge.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 17 AND name = 'Martin Bucer';
UPDATE figures SET known_for = 'Carey helped found the Baptist Missionary Society and went to India, which helped launch the modern Protestant missionary movement.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 18 AND name = 'William Carey';
UPDATE figures SET known_for = 'Tozer wrote The Pursuit of God and The Knowledge of the Holy, which called evangelicals back to a deep personal hunger for God.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 19 AND name = 'A.W. Tozer';
UPDATE figures SET known_for = 'Hus called for church reform in Prague a century before Luther, and his execution at Constance sparked the Hussite movement in Bohemia.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 20 AND name = 'Jan Hus';
UPDATE figures SET known_for = 'Schaeffer opened L''Abri with his wife Edith and taught a generation of evangelicals to engage art, philosophy and culture.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 21 AND name = 'Francis Schaeffer';
UPDATE figures SET known_for = 'Lloyd-Jones left medicine to preach and helped revive verse by verse Bible preaching among British evangelicals from Westminster Chapel in London.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 22 AND name = 'Martyn Lloyd-Jones';
UPDATE figures SET known_for = 'Nee founded the Little Flock churches of China, and his books The Normal Christian Life and The Spiritual Man found readers worldwide.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 23 AND name = 'Watchman Nee';
UPDATE figures SET known_for = 'Fénelon wrote spiritual letters on surrender to God that Catholics and Protestants such as the Quakers have used as guides to prayer.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 24 AND name = 'François Fénelon';
UPDATE figures SET known_for = 'Madame Guyon wrote A Short and Very Easy Method of Prayer, a guide later taken up by Quakers and by Watchman Nee.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 25 AND name = 'Madame Guyon';
UPDATE figures SET known_for = 'Thomas à Kempis is generally credited with The Imitation of Christ, for centuries the most widely read Christian devotional book after the Bible.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 26 AND name = 'Thomas à Kempis';
UPDATE figures SET known_for = 'Brother Lawrence prayed while cooking, and the talks and letters published as The Practice of the Presence of God reached Catholics and Protestants.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 27 AND name = 'Brother Lawrence';
UPDATE figures SET known_for = 'Julian wrote Revelations of Divine Love, a book on God''s love that found many new readers after a modern English version appeared in 1901.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 28 AND name = 'Julian of Norwich';
UPDATE figures SET known_for = 'John of the Cross wrote Dark Night of the Soul on prayer when God seems absent, and the title became an everyday English phrase.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 29 AND name = 'John of the Cross';
UPDATE figures SET known_for = 'Teresa wrote The Interior Castle on the life of prayer and in 1970 became the first woman named a Doctor of the Church.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 30 AND name = 'Teresa of Ávila';
UPDATE figures SET known_for = 'Bernard preached sermons on the Song of Songs and the love of Christ that shaped medieval devotion and were admired by Luther and Calvin.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 31 AND name = 'Bernard of Clairvaux';
UPDATE figures SET known_for = 'Francis gave up wealth to follow Christ in poverty, and the Franciscan friars carried that way of life across Europe and the world.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 32 AND name = 'Francis of Assisi';
UPDATE figures SET known_for = 'Hildegard recorded visions in Scivias and wrote sacred songs still sung today, and in 2012 became a Doctor of the Church.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 33 AND name = 'Hildegard of Bingen';
UPDATE figures SET known_for = 'Caussade is traditionally credited with Abandonment to Divine Providence, a book on finding God in the present moment read widely since 1861.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 34 AND name = 'Jean-Pierre de Caussade';
UPDATE figures SET known_for = 'Rolle wrote The Fire of Love and guides to prayer that made him the most copied English writer of the late Middle Ages.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 35 AND name = 'Richard Rolle';
UPDATE figures SET known_for = 'Augustine wrote Confessions and The City of God, and his teaching on sin and grace shaped both Catholic and Protestant thought.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 36 AND name = 'Augustine of Hippo';
UPDATE figures SET known_for = 'Athanasius defended the Nicene Creed through five exiles, which kept the belief that Christ is fully God at the heart of Christian faith.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 37 AND name = 'Athanasius';
UPDATE figures SET known_for = 'Chrysostom was the greatest preacher of the early Greek church, and the liturgy bearing his name is still used on most Sundays in Orthodox churches.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 38 AND name = 'John Chrysostom';
UPDATE figures SET known_for = 'Origen was the first great Bible scholar of the church, and his commentaries shaped how Christians read Scripture for centuries.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 39 AND name = 'Origen';
UPDATE figures SET known_for = 'Polycarp was a disciple of the apostle John, and the account of his martyrdom is the earliest record of a church honoring a martyr each year.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 40 AND name = 'Polycarp';
UPDATE figures SET known_for = 'Ignatius wrote seven letters on his way to execution in Rome, which give the earliest picture of churches each led by a single bishop.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 41 AND name = 'Ignatius of Antioch';
UPDATE figures SET known_for = 'Irenaeus wrote Against Heresies to answer the Gnostics, and his case for exactly four Gospels helped make them the church''s accepted Gospels.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 42 AND name = 'Irenaeus';
UPDATE figures SET known_for = 'Clement taught in Alexandria and argued that Greek philosophy helped prepare people for the gospel.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 43 AND name = 'Clement of Alexandria';
UPDATE figures SET known_for = 'Cyprian led the church in Carthage through persecution and plague and wrote On the Unity of the Church.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 44 AND name = 'Cyprian of Carthage';
UPDATE figures SET known_for = 'Basil wrote rules for monks and founded a large center outside Caesarea to care for the poor and sick.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 45 AND name = 'Basil the Great';
UPDATE figures SET known_for = 'Gregory of Nyssa helped shape the teaching on the Trinity affirmed at the Council of Constantinople.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 46 AND name = 'Gregory of Nyssa';
UPDATE figures SET known_for = 'Gregory of Nazianzus preached the Theological Orations, five sermons on the Trinity given in Constantinople.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 47 AND name = 'Gregory of Nazianzus';
UPDATE figures SET known_for = 'Ambrose introduced congregational hymn singing to the Latin church and baptized Augustine in Milan.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 48 AND name = 'Ambrose of Milan';
UPDATE figures SET known_for = 'Jerome translated the Old Testament from Hebrew into Latin, work at the heart of the Bible known as the Vulgate.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 49 AND name = 'Jerome';
UPDATE figures SET known_for = 'Justin was the first great Christian apologist, and his defense of the faith to the Roman emperor set the pattern for those who followed.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 50 AND name = 'Justin Martyr';
UPDATE figures SET known_for = 'King led the nonviolent civil rights movement, which helped win the Civil Rights Act of 1964 and the Voting Rights Act of 1965.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 51 AND name = 'Martin Luther King Jr.';
UPDATE figures SET known_for = 'Wilberforce led the campaign in Parliament that ended the British slave trade in 1807.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 52 AND name = 'William Wilberforce';
UPDATE figures SET known_for = 'Tubman escaped slavery and then returned many times to guide others to freedom on the Underground Railroad.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 53 AND name = 'Harriet Tubman';
UPDATE figures SET known_for = 'Truth escaped slavery and became a traveling preacher who spoke across the North against slavery and for women''s rights.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 54 AND name = 'Sojourner Truth';
UPDATE figures SET known_for = 'Tutu won the Nobel Peace Prize for opposing apartheid and later led South Africa''s Truth and Reconciliation Commission.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 55 AND name = 'Desmond Tutu';
UPDATE figures SET known_for = 'Douglass escaped slavery and became the leading Black voice for abolition, and later for equal rights after the Civil War.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 56 AND name = 'Frederick Douglass';
UPDATE figures SET known_for = 'Lincoln led the Union through the Civil War and pushed through the 13th Amendment, which ended slavery in the United States.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 57 AND name = 'Abraham Lincoln';
UPDATE figures SET known_for = 'Corrie ten Boom survived a Nazi camp after hiding Jewish people and spent the rest of her life preaching forgiveness around the world.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 58 AND name = 'Corrie ten Boom';
UPDATE figures SET known_for = 'Liddell left his Olympic fame behind to serve as a missionary in China, and his story of faith over sport inspired Chariots of Fire.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 59 AND name = 'Eric Liddell';
UPDATE figures SET known_for = 'Shaftesbury led reforms in Parliament that limited child labor in British factories and mines.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 60 AND name = 'Lord Shaftesbury';
UPDATE figures SET known_for = 'Finney led revivals in the Second Great Awakening, and his new measures shaped how later American evangelists ran revival meetings.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 61 AND name = 'Charles Finney';
UPDATE figures SET known_for = 'Newton was a slave ship captain who became a minister, wrote Amazing Grace and later joined Wilberforce''s fight against the slave trade.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 62 AND name = 'John Newton';
UPDATE figures SET known_for = 'Equiano wrote The Interesting Narrative, a 1789 account of enslavement that fed the campaign against the slave trade.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 63 AND name = 'Olaudah Equiano';
UPDATE figures SET known_for = 'Thurman wrote Jesus and the Disinherited, a 1949 book that influenced leaders of the civil rights movement.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 64 AND name = 'Howard Thurman';
