UPDATE figures SET known_for = 'Kierkegaard wrote Either/Or and Fear and Trembling and is often called the first existentialist philosopher.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 77 AND name = 'Søren Kierkegaard';
