UPDATE figures SET known_for = 'Lennox is an Oxford mathematician whose books and debates with leading atheists have made him a prominent voice for faith in an age of science.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 80 AND name = 'John Lennox';
