UPDATE figures SET known_for = 'Elliot was killed with four fellow missionaries in Ecuador, and news of the killings drew many young Americans into missionary work.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 85 AND name = 'Jim Elliot';
