UPDATE figures SET known_for = 'Aylward led about a hundred children across the mountains to safety during the Japanese invasion of China.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 92 AND name = 'Gladys Aylward';
UPDATE figures SET known_for = 'Studd gave up cricket fame and a fortune to be a missionary and founded WEC International, which still sends missionaries worldwide.', updated_at = (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT WHERE id = 93 AND name = 'C.T. Studd';
